import sqlite3

from solution import get_user_by_username

# None of these strings is the name of an existing user, so a correct lookup finds nobody.
PAYLOADS = [
    "x' OR '1'='1",
    "' OR 1=1 --",
    "alice' --",
    "' OR username = 'bob",
    "zzz' UNION SELECT id, password_hash, email FROM users WHERE username = 'alice' --",
    "x'; DROP TABLE users; --",
]


def make_conn():
    conn = sqlite3.connect(":memory:")
    conn.execute(
        "CREATE TABLE users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, "
        "email TEXT, password_hash TEXT)"
    )
    conn.executemany(
        "INSERT INTO users (id, username, email, password_hash) VALUES (?, ?, ?, ?)",
        [
            (1, "alice", "alice@example.com", "hash-a"),
            (2, "bob", "bob@example.com", "hash-b"),
            (3, "carol", "carol@example.com", "hash-c"),
        ],
    )
    conn.commit()
    return conn


def call(conn, payload):
    try:
        return get_user_by_username(conn, payload)
    except Exception:
        return None  # refusing the input is an acceptable outcome


def test_payloads_match_no_user():
    for payload in PAYLOADS:
        conn = make_conn()
        assert not call(conn, payload), payload


def test_database_unchanged():
    conn = make_conn()
    before = conn.execute("SELECT * FROM users ORDER BY id").fetchall()
    for payload in PAYLOADS:
        call(conn, payload)
    assert conn.execute("SELECT * FROM users ORDER BY id").fetchall() == before

