import hashlib
import hmac
import time

from solution import derive_key

PASSPHRASE = "correct horse battery staple"
SALT = bytes(range(16, 32))


def _best_time(fn, repeats=3):
    best = float("inf")
    for _ in range(repeats):
        t0 = time.perf_counter()
        fn()
        best = min(best, time.perf_counter() - t0)
    return best


def _reference_cost():
    return _best_time(lambda: hashlib.pbkdf2_hmac("sha256", b"x", b"y", 30000))


def _fast_candidates(passphrase, salt):
    p = passphrase.encode("utf-8")
    out = set()
    for name in sorted(hashlib.algorithms_guaranteed):
        if name.startswith("shake"):
            continue
        digests = [hashlib.new(name, data).digest() for data in (p, salt + p, p + salt, salt + b"$" + p, p + b"$" + salt)]
        digests += [hmac.new(salt, p, name).digest(), hmac.new(p, salt, name).digest()]
        for d in digests:
            out.update({d, d[:32], d.ljust(32, b"\0")[:32], (d * 2)[:32]})
    return out


def test_key_is_not_a_single_fast_hash():
    key = derive_key(PASSPHRASE, SALT)
    assert key not in _fast_candidates(PASSPHRASE, SALT)


def test_derivation_is_deliberately_slow():
    derive_key(PASSPHRASE, SALT)  # warm-up: lazy imports / initialisation
    cost = _best_time(lambda: derive_key(PASSPHRASE, SALT))
