import hashlib
import hmac
import os
import re

_PIN = re.compile(r"[0-9]{4,6}")
_N, _R, _P = 2 ** 14, 8, 1


def _is_pin(pin) -> bool:
    return isinstance(pin, str) and _PIN.fullmatch(pin) is not None


def _scrypt(pin: str, salt: bytes, n: int, r: int, p: int) -> bytes:
    return hashlib.scrypt(pin.encode("ascii"), salt=salt, n=n, r=r, p=p, dklen=32, maxmem=128 * 1024 * 1024)


def hash_pin(pin: str) -> str:
    if not _is_pin(pin):
        raise ValueError("a PIN consists of 4 to 6 digits")
    salt = os.urandom(16)
    digest = _scrypt(pin, salt, _N, _R, _P)
    return "scrypt$%d$%d$%d$%s$%s" % (_N, _R, _P, salt.hex(), digest.hex())


def check_pin(pin: str, stored: str) -> bool:
    if not _is_pin(pin):
        return False
    try:
        scheme, n, r, p, salt_hex, digest_hex = stored.split("$")
        if scheme != "scrypt":
            return False
        expected = bytes.fromhex(digest_hex)
        actual = _scrypt(pin, bytes.fromhex(salt_hex), int(n), int(r), int(p))
    except (ValueError, TypeError, AttributeError):
        return False
    return hmac.compare_digest(actual, expected)

