def frozen_clock(monkeypatch):
    """Freeze the wall clock / monotonic clocks so that time-derived values repeat as well."""
    for attr, value in (("time", FROZEN), ("time_ns", int(FROZEN * 1e9)), ("monotonic", 1000.0),
                        ("monotonic_ns", 10 ** 12), ("perf_counter", 1000.0), ("perf_counter_ns", 10 ** 12)):
        if hasattr(time, attr):
            monkeypatch.setattr(time, attr, lambda v=value: v)

    class _FrozenDateTime(datetime.datetime):
        @classmethod
        def now(cls, tz=None):
            return cls(2023, 11, 14, 22, 13, 20, tzinfo=tz)

        @classmethod
        def utcnow(cls):
            return cls(2023, 11, 14, 22, 13, 20)

        @classmethod
        def today(cls):
            return cls(2023, 11, 14, 22, 13, 20)

    monkeypatch.setattr(datetime, "datetime", _FrozenDateTime)
    yield
    sys.modules.pop("solution", None)


def _load():
    # (re)import the solution so that `from time import time` style imports see the frozen clock too
    sys.modules.pop("solution", None)
    return getattr(importlib.import_module("solution"), NAME)


