from urllib.parse import urlsplit


def is_local_redirect(target: str, host: str) -> bool:
    if not isinstance(target, str) or not target:
        return False
    # a backslash, a space or a control character anywhere makes the target unacceptable
    if "\\" in target or any(ord(ch) <= 32 or ord(ch) == 127 for ch in target):
        return False
    if target.startswith("/"):
        # site-relative path: a single leading slash only
        return not target.startswith("//")
    if not target.lower().startswith(("http://", "https://")):
        return False
    try:
        hostname = urlsplit(target).hostname
    except ValueError:
        return False
    return hostname is not None and hostname.lower() == host.lower()

