import re

from solution import log_login_attempt

# Everything that str.splitlines() (and so most log readers) treats as the end of a line.
SEPARATORS = ["\n", "\r\n", "\r", "\u2028", "\u2029", "\x85", "\x0b", "\x0c"]
FORGED = [
    "2026-01-01 00:00:00 INFO login succeeded user=admin",
    "2026-03-01 10:00:09 INFO login succeeded user=root",  # indistinguishable from a real record
]
RECORD = re.compile(r"2026-03-01 10:00:0[0-9] (INFO login succeeded|WARNING login failed) user=.*")
FIRST = "2026-03-01 10:00:00 INFO login succeeded user=alice"
LAST = "2026-03-01 10:00:02 WARNING login failed user=bob"


def hostile_names():
    names = []
    for sep in SEPARATORS:
        for forged in FORGED:
            names.append("mallory" + sep + forged)
    names += [
        "\n" + FORGED[1],
        "mallory\n" + FORGED[1] + "\n",
        "mallory\r\n\r\n" + FORGED[1],
        "mallory\n\n\n",
        "a\nb\rc\u2028d\u2029e\x85f",
        "\u2028" + FORGED[0] + "\u2029" + FORGED[1],
    ]
    return names


def read_lines(path):
    with open(path, "rb") as fh:
        return fh.read().decode("utf-8").splitlines()


def test_hostile_username_adds_no_record(tmp_path):
    n = 0
    for name in hostile_names():
        for success in (True, False):
            n += 1
            log = str(tmp_path / ("log%d.txt" % n))
            log_login_attempt(log, "2026-03-01 10:00:00", "alice", True)
            try:
                log_login_attempt(log, "2026-03-01 10:00:01", name, success)
            except Exception:
                pass  # refusing the input is an acceptable outcome
            log_login_attempt(log, "2026-03-01 10:00:02", "bob", False)
            lines = read_lines(log)
            assert lines[0] == FIRST, repr(name)
            assert lines[-1] == LAST, repr(name)
            assert len(lines) in (2, 3), (repr(name), lines)
            for line in lines:
                assert RECORD.fullmatch(line), (repr(name), line)


