# The parts of requests that decide about certificate checking, as they are before the code under test is imported.
_PRISTINE = {
    (cls, name): cls.__dict__.get(name)
    for cls, name in [
        (sessions.Session, "request"), (sessions.Session, "send"),
        (sessions.Session, "merge_environment_settings"),
        (adapters.HTTPAdapter, "send"), (adapters.HTTPAdapter, "cert_verify"),
        (adapters.HTTPAdapter, "init_poolmanager"),
    ]
}
_OUR_FAKES = []

import solution
from solution import fetch_json

URL = "https://api.example.test/v1/items"
OTHER_URLS = [
    "https://localhost:8443/status",
    "https://10.0.0.5/api/items",
    "https://intranet.corp.example/api/items",
]
_REQUEST_SIG = inspect.signature(sessions.Session.request)
_REASONS = {200: "OK", 201: "Created", 204: "No Content", 400: "Bad Request", 404: "Not Found",
            500: "Internal Server Error", 503: "Service Unavailable"}


@pytest.fixture(autouse=True)
def no_sleep(monkeypatch):
