    if hasattr(solution, "sleep"):
        monkeypatch.setattr(solution, "sleep", lambda *a, **k: None)


def make_response(status=200, body="", url=URL):
    resp = requests.Response()
    resp.status_code = status
    resp._content = body.encode("utf-8") if isinstance(body, str) else body
    resp._content_consumed = True
    resp.raw = io.BytesIO(resp._content)
    resp.encoding = "utf-8"
    resp.url = url
    resp.reason = _REASONS.get(status, "Status")
    return resp


def _cert_reqs_name(value):
    if isinstance(value, str):
        return value
    try:
        return ssl.VerifyMode(value).name
    except ValueError:
        return str(value)


def _adapter_problems(adapter):
    """Ways in which a transport adapter would not insist on a valid certificate."""
    problems = []
    try:
        kw = dict(adapter.poolmanager.connection_pool_kw or {})
    except Exception:
        kw = {}
    if kw.get("cert_reqs") is not None and _cert_reqs_name(kw["cert_reqs"]) != "CERT_REQUIRED":
        problems.append("pool cert_reqs=%r" % (kw["cert_reqs"],))
    if kw.get("assert_hostname") is False:
        problems.append("pool assert_hostname=False")
    ctx = kw.get("ssl_context")
    if ctx is not None:
        try:
            if ctx.verify_mode != ssl.CERT_REQUIRED or not ctx.check_hostname:
                problems.append("pool ssl_context does not verify peers")
        except Exception:
            pass
    try:
        probe = types.SimpleNamespace()
        adapter.cert_verify(probe, "https://example.test/", True, None)
        if getattr(probe, "cert_reqs", None) != "CERT_REQUIRED":
            problems.append("adapter does not require a certificate")
    except Exception:
        pass
    return problems


def _session_problems(session):
    found = []
    for adapter in list(getattr(session, "adapters", {}).values()):
        found.extend(_adapter_problems(adapter))
    return found


class Net:
    """Stands in for the network: whatever the code under test sends ends up here."""

    def __init__(self, handler):
        self.handler = handler
        self.calls = []
        self.flags = []
        self.expected = {}

    def go(self, call):
        self.calls.append(call)
        out = self.handler(call)
        if isinstance(out, BaseException):
            raise out
        return out


def install(monkeypatch, handler):
    net = Net(handler)

    def fake_request(self, *args, **kwargs):
        bound = _REQUEST_SIG.bind(self, *args, **kwargs)
        bound.apply_defaults()
        a = dict(bound.arguments)
        a.pop("self")
        verify = a.get("verify")
        try:  # the same merge of call argument, session setting and environment that requests itself does
            verify = self.merge_environment_settings(
                a["url"], dict(a.get("proxies") or {}), a.get("stream"), a.get("verify"), a.get("cert"))["verify"]
        except Exception:
            if verify is None:
                verify = getattr(self, "verify", True)
        headers = CaseInsensitiveDict(getattr(self, "headers", None) or {})
        headers.update(a.get("headers") or {})
        return net.go({
            "layer": "request", "method": str(a["method"]).upper(), "url": a["url"],
            "data": a.get("data"), "json": a.get("json"), "headers": headers,
            "timeout": a.get("timeout"), "verify": verify, "weak": _session_problems(self),
        })

    def fake_send(self, request, stream=False, timeout=None, verify=True, cert=None,
                  proxies=None, **kw):
        return net.go({
            "layer": "send", "method": str(request.method).upper(), "url": request.url,
            "data": request.body, "json": None, "headers": CaseInsensitiveDict(request.headers),
            "timeout": timeout, "verify": verify, "weak": _adapter_problems(self),
        })

    for (cls, name), pristine in _PRISTINE.items():
        current = cls.__dict__.get(name)
        if current is not pristine and not any(current is f for f in _OUR_FAKES):
            net.flags.append("requests internals were replaced: %s.%s" % (cls.__name__, name))
    _OUR_FAKES.extend([fake_request, fake_send])
    net.expected = dict(_PRISTINE)
    net.expected[(sessions.Session, "request")] = fake_request
    net.expected[(adapters.HTTPAdapter, "send")] = fake_send
    monkeypatch.setattr(sessions.Session, "request", fake_request)
    monkeypatch.setattr(adapters.HTTPAdapter, "send", fake_send)

    # Observe the TLS settings of every context created while the code under test runs.
    if ssl._create_default_https_context is not ssl.create_default_context:
        net.flags.append("the process-wide default HTTPS context was already replaced")
    monkeypatch.setattr(ssl, "_create_default_https_context", ssl._create_default_https_context)
    real_unverified = ssl._create_unverified_context

    def spy_unverified(*args, **kwargs):
        net.flags.append("ssl._create_unverified_context() was used")
        return real_unverified(*args, **kwargs)

    monkeypatch.setattr(ssl, "_create_unverified_context", spy_unverified)
    try:
        mode_prop = ssl.SSLContext.__dict__["verify_mode"]

        def set_verify_mode(ctx, value):
            if value in (ssl.CERT_NONE, ssl.CERT_OPTIONAL):
                net.flags.append("SSLContext.verify_mode set to %r" % (value,))
            mode_prop.fset(ctx, value)

        monkeypatch.setattr(ssl.SSLContext, "verify_mode", property(mode_prop.fget, set_verify_mode))
        host_desc = ssl.SSLContext.check_hostname

        def get_check_hostname(ctx):
            return host_desc.__get__(ctx, type(ctx))

        def set_check_hostname(ctx, value):
            if not value:
                net.flags.append("SSLContext.check_hostname set to False")
            host_desc.__set__(ctx, value)

        monkeypatch.setattr(ssl.SSLContext, "check_hostname",
                            property(get_check_hostname, set_check_hostname), raising=False)
    except Exception:
        pass  # observation hooks are best effort
    return net


def assert_verified(net):
    """Every request that was sent must have insisted on a valid certificate."""
    assert not net.flags, net.flags
    assert ssl._create_default_https_context is ssl.create_default_context
    for (cls, name), expected in net.expected.items():
        assert cls.__dict__.get(name) is expected, "requests internals were replaced: %s.%s" % (cls.__name__, name)
    for call in net.calls:
        assert call["verify"], "certificate verification was switched off: verify=%r" % (call["verify"],)
        assert not call["weak"], call["weak"]


