        return record.getMessage()
    except Exception:
        return str(record.msg)


def messages(handler, min_level=logging.INFO):
    return [message(r) for r in handler.records if r.levelno >= min_level]


def everything(handler, capsys):
    """All text that the code under test emitted: messages, arguments, extras, tracebacks, stdout, stderr."""
    parts = []
    for record in handler.records:
        parts.append(message(record))
        try:
            parts.append(repr(record.__dict__))
        except Exception:
            pass
        if record.exc_info:
            try:
                parts.append(logging.Formatter().formatException(record.exc_info))
            except Exception:
                pass
    out, err = capsys.readouterr()
    parts.extend([out, err])
    return "\n".join(parts)


def _views(text):
    """The text itself plus whatever can be decoded out of it (base64 / hex runs, digit groups)."""
    views = [text, re.sub(r"(?<=\d)[ \-._/](?=\d)", "", text)]
    for match in re.finditer(r"[A-Za-z0-9+/_-]{8,}={0,2}", text):
        chunk = match.group(0)
        for skip in range(4):
            part = chunk[skip:]
            part += "=" * (-len(part) % 4)
            for decode in (base64.b64decode, base64.urlsafe_b64decode):
                try:
                    views.append(decode(part).decode("utf-8", "ignore"))
                except (binascii.Error, ValueError):
                    pass
    for match in re.finditer(r"(?:[0-9a-fA-F]{2}){4,}", text):
        try:
            views.append(bytes.fromhex(match.group(0)).decode("utf-8", "ignore"))
        except ValueError:
            pass
    return views


def leaked(secret, text, window=8):
    """True if the secret, or any run of `window` consecutive characters of it (also reversed,
    base64- or hex-encoded, case ignored), shows up in the text. Showing a short prefix or
    suffix of the secret (fewer than `window` characters) is not counted."""
    forms = {secret.lower(), secret[::-1].lower()}
    for view in _views(text):
        low = view.lower()
        for form in forms:
            if len(form) <= window:
                if form in low:
                    return True
            elif any(form[i:i + window] in low for i in range(len(form) - window + 1)):
                return True
    return False


