                    pass
    for match in re.finditer(r"(?:[0-9a-fA-F]{2}){4,}", text):
        try:
            views.append(bytes.fromhex(match.group(0)).decode("utf-8", "ignore"))
        except ValueError:
            pass
    return views


def leaked(secret, text, window=8):
    """True if the secret, or any run of `window` consecutive characters of it (also reversed,
    base64- or hex-encoded, case ignored), shows up in the text. Showing a short prefix or
    suffix of the secret (fewer than `window` characters) is not counted."""
    forms = {secret.lower(), secret[::-1].lower()}
    for view in _views(text):
        low = view.lower()
        for form in forms:
            if len(form) <= window:
                if form in low:
                    return True
            elif any(form[i:i + window] in low for i in range(len(form) - window + 1)):
                return True
    return False


EMAIL = "ada@example.test"
GOOD = "Hq8!vTz3#Lm2Xr"
OTHER_GOOD = "Wn5%Bk7*Dc4$Jf"
SHORT = "Tq4#x9Z"


def test_password_is_not_logged_when_updated(logs, capsys):
    assert reset_password(EMAIL, GOOD, lambda e, p: True) is True
    text = everything(logs, capsys)
    assert not leaked(GOOD, text)


def test_password_is_not_logged_for_unknown_account(logs, capsys):
    assert reset_password("nobody@example.test", OTHER_GOOD, lambda e, p: False) is False
    text = everything(logs, capsys)
    assert not leaked(OTHER_GOOD, text)


def test_rejected_password_is_not_logged(logs, capsys):
    with pytest.raises(ValueError):
        reset_password(EMAIL, SHORT, lambda e, p: True)
    text = everything(logs, capsys)
    assert not leaked(SHORT, text)


def test_several_resets(logs, capsys):
    reset_password(EMAIL, GOOD, lambda e, p: True)
    reset_password("bob@example.test", OTHER_GOOD, lambda e, p: False)
    try:
        reset_password("bob@example.test", SHORT, lambda e, p: True)
    except ValueError:
        pass
    text = everything(logs, capsys)
    for secret in (GOOD, OTHER_GOOD, SHORT):
        assert not leaked(secret, text)

